// Import of required libraries
import { test, expect, SkyrampClient, getBaseUrl, getValue, getResponseValue } from '@skyramp/skyramp';
import { createCollection, createLink, createHighlight, getHighlights, deleteLink, deleteCollection } from './skyrampUtils';

// URL for test requests
const URL_localhost = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:3000");

test('testIntegration', async () => {
    test.setTimeout(60000);

    // Invocation of Skyramp Client
    const client = new SkyrampClient();
    // Definition of authentication header
    const headers: Record<string, string> = {};
    if (process.env.SKYRAMP_TEST_TOKEN && process.env.SKYRAMP_TEST_TOKEN != "") {
        headers["Authorization"] = "Bearer " + process.env.SKYRAMP_TEST_TOKEN;
    }

    // Request Body
    const collectionsPostRequestBody: string = `{
        "name": "Highlights Library Filters"
    }`;

    // Request Body
    const linksPostRequestBody: string = `{
        "collection": {
            "id": 101
        },
        "name": "Highlights Filters Source",
        "tags": [],
        "type": "url",
        "url": "https://example.com/hl-filters"
    }`;

    // Request Body
    const highlightsPostRequestBody: string = `{
        "color": "yellow",
        "comment": "alpha note",
        "endOffset": 19,
        "linkId": 201,
        "startOffset": 0,
        "text": "Zephyr filter alpha"
    }`;

    // Request Body
    const highlightsPost1RequestBody: string = `{
        "color": "green",
        "comment": "beta note",
        "endOffset": 38,
        "linkId": 201,
        "startOffset": 20,
        "text": "Zephyr filter beta"
    }`;

    // Request Body
    const highlightsPost2RequestBody: string = `{
        "color": "blue",
        "comment": "gamma note",
        "endOffset": 57,
        "linkId": 201,
        "startOffset": 40,
        "text": "Unrelated passage"
    }`;

    const take = "2";

    const collectionsPostResponse = await createCollection(client, URL_localhost, headers, collectionsPostRequestBody);
    expect(collectionsPostResponse.statusCode, 'status code').toBe(200);
    expect(getResponseValue(collectionsPostResponse, "response.name"), 'collection name').toBe("Highlights Library Filters");
    expect(getResponseValue(collectionsPostResponse, "response.id"), 'collection id').toBeGreaterThan(0);
    const linksPostResponse = await createLink(client, URL_localhost, headers, linksPostRequestBody, {"collection.id": getResponseValue(collectionsPostResponse, "response.id")});
    expect(linksPostResponse.statusCode, 'status code').toBe(200);
    const linkId = getResponseValue(linksPostResponse, "response.id");
    expect(getResponseValue(linksPostResponse, "response.name"), 'link name').toBe("Highlights Filters Source");
    expect(getResponseValue(linksPostResponse, "response.url"), 'link url').toBe("https://example.com/hl-filters");
    expect(getResponseValue(linksPostResponse, "response.collectionId"), 'link collection').toBe(getResponseValue(collectionsPostResponse, "response.id"));

    const highlightsPostResponse = await createHighlight(client, URL_localhost, headers, highlightsPostRequestBody, {"linkId": linkId});
    expect(highlightsPostResponse.statusCode, 'status code').toBe(200);
    expect(getResponseValue(highlightsPostResponse, "response.color"), 'yellow highlight colour').toBe("yellow");
    expect(getResponseValue(highlightsPostResponse, "response.text"), 'yellow highlight text').toBe("Zephyr filter alpha");
    expect(getResponseValue(highlightsPostResponse, "response.comment"), 'yellow highlight comment').toBe("alpha note");
    expect(getResponseValue(highlightsPostResponse, "response.startOffset"), 'yellow highlight startOffset').toBe(0);
    expect(getResponseValue(highlightsPostResponse, "response.endOffset"), 'yellow highlight endOffset').toBe(19);
    expect(getResponseValue(highlightsPostResponse, "response.linkId"), 'yellow highlight link').toBe(linkId);
    const highlightsPost1Response = await createHighlight(client, URL_localhost, headers, highlightsPost1RequestBody, {"linkId": linkId});
    expect(highlightsPost1Response.statusCode, 'status code').toBe(200);
    expect(getResponseValue(highlightsPost1Response, "response.color"), 'green highlight colour').toBe("green");
    expect(getResponseValue(highlightsPost1Response, "response.text"), 'green highlight text').toBe("Zephyr filter beta");
    expect(getResponseValue(highlightsPost1Response, "response.comment"), 'green highlight comment').toBe("beta note");
    expect(getResponseValue(highlightsPost1Response, "response.linkId"), 'green highlight link').toBe(linkId);
    const highlightsPost2Response = await createHighlight(client, URL_localhost, headers, highlightsPost2RequestBody, {"linkId": linkId});
    expect(highlightsPost2Response.statusCode, 'status code').toBe(200);
    expect(getResponseValue(highlightsPost2Response, "response.color"), 'blue highlight colour').toBe("blue");
    expect(getResponseValue(highlightsPost2Response, "response.text"), 'blue highlight text').toBe("Unrelated passage");
    expect(getResponseValue(highlightsPost2Response, "response.comment"), 'blue highlight comment').toBe("gamma note");
    expect(getResponseValue(highlightsPost2Response, "response.linkId"), 'blue highlight link').toBe(linkId);

    const highlightsGetResponse = await getHighlights(client, URL_localhost, headers);
    expect(highlightsGetResponse.statusCode, 'status code').toBe(200);
    expect(getResponseValue(highlightsGetResponse, "response.highlights").length, 'library holds the three created highlights').toBe(3);
    expect(getResponseValue(highlightsGetResponse, "response.highlights.0.id"), 'newest highlight first').toBe(getResponseValue(highlightsPost2Response, "response.id"));
    expect(getResponseValue(highlightsGetResponse, "response.highlights.1.id"), 'second newest').toBe(getResponseValue(highlightsPost1Response, "response.id"));
    expect(getResponseValue(highlightsGetResponse, "response.highlights.2.id"), 'oldest last').toBe(getResponseValue(highlightsPostResponse, "response.id"));
    expect(getResponseValue(highlightsGetResponse, "response.highlights.3"), 'no fourth highlight').toBeNull();
    expect(getResponseValue(highlightsGetResponse, "response.highlights.0.link.id"), 'link attached').toBe(linkId);
    expect(getResponseValue(highlightsGetResponse, "response.highlights.0.link.name"), 'link name attached').toBe("Highlights Filters Source");
    expect(getResponseValue(highlightsGetResponse, "response.highlights.0.link.url"), 'link url attached').toBe("https://example.com/hl-filters");
    expect(getResponseValue(highlightsGetResponse, "response.nextCursor"), 'single page').toBeNull();

    const highlightsGet1Response = await getHighlights(client, URL_localhost, headers, {"color": ["green"]});
    expect(highlightsGet1Response.statusCode, 'status code').toBe(200);
    expect(getResponseValue(highlightsGet1Response, "response.highlights").length, 'only the green highlight').toBe(1);
    expect(getResponseValue(highlightsGet1Response, "response.highlights.0.id"), 'the green highlight').toBe(getResponseValue(highlightsPost1Response, "response.id"));
    expect(getResponseValue(highlightsGet1Response, "response.highlights.0.color"), 'filter honoured').toBe("green");
    expect(getResponseValue(highlightsGet1Response, "response.highlights.1"), 'no second green highlight').toBeNull();
    expect(getResponseValue(highlightsGet1Response, "response.nextCursor"), 'single page').toBeNull();

    const highlightsGet2Response = await getHighlights(client, URL_localhost, headers, {"q": ["Zephyr"]});
    expect(highlightsGet2Response.statusCode, 'status code').toBe(200);
    expect(getResponseValue(highlightsGet2Response, "response.highlights").length, 'both Zephyr highlights').toBe(2);
    expect(getResponseValue(highlightsGet2Response, "response.highlights.0.id"), 'newest Zephyr highlight first').toBe(getResponseValue(highlightsPost1Response, "response.id"));
    expect(getResponseValue(highlightsGet2Response, "response.highlights.1.id"), 'older Zephyr highlight second').toBe(getResponseValue(highlightsPostResponse, "response.id"));
    expect(getResponseValue(highlightsGet2Response, "response.highlights.2"), 'the unrelated passage is excluded').toBeNull();

    const highlightsGet3Response = await getHighlights(client, URL_localhost, headers, {"q": ["BETA NOTE"]});
    expect(highlightsGet3Response.statusCode, 'status code').toBe(200);
    expect(getResponseValue(highlightsGet3Response, "response.highlights").length, 'comment matched ignoring case').toBe(1);
    expect(getResponseValue(highlightsGet3Response, "response.highlights.0.id"), 'the highlight whose comment matched').toBe(getResponseValue(highlightsPost1Response, "response.id"));
    expect(getResponseValue(highlightsGet3Response, "response.highlights.0.comment"), 'matched comment').toBe("beta note");
    expect(getResponseValue(highlightsGet3Response, "response.highlights.1"), 'no other comment matched').toBeNull();

    const highlightsGet4Response = await getHighlights(client, URL_localhost, headers, {"q": ["nothingmatchesthis"]});
    expect(highlightsGet4Response.statusCode, 'status code').toBe(200);
    expect(getResponseValue(highlightsGet4Response, "response.highlights").length, 'a term matching nothing returns nothing').toBe(0);
    expect(getResponseValue(highlightsGet4Response, "response.highlights.0"), 'empty list').toBeNull();
    expect(getResponseValue(highlightsGet4Response, "response.nextCursor"), 'no next page').toBeNull();

    const highlightsGet5Response = await getHighlights(client, URL_localhost, headers, {"take": [take]});
    expect(highlightsGet5Response.statusCode, 'status code').toBe(200);
    expect(getResponseValue(highlightsGet5Response, "response.highlights").length, 'page honours take').toBe(2);
    expect(getResponseValue(highlightsGet5Response, "response.highlights.0.id"), 'first page newest first').toBe(getResponseValue(highlightsPost2Response, "response.id"));
    expect(getResponseValue(highlightsGet5Response, "response.highlights.1.id"), 'first page second item').toBe(getResponseValue(highlightsPost1Response, "response.id"));
    expect(getResponseValue(highlightsGet5Response, "response.highlights.2"), 'page trimmed to take').toBeNull();
    expect(getResponseValue(highlightsGet5Response, "response.nextCursor"), 'cursor is the last id on this page').toBe(getResponseValue(highlightsPost1Response, "response.id"));

    const highlightsGet6Response = await getHighlights(client, URL_localhost, headers, {
        "cursor": [getResponseValue(highlightsGet5Response, "response.nextCursor")],
        "take": [take]
    });
    expect(highlightsGet6Response.statusCode, 'status code').toBe(200);
    expect(getResponseValue(highlightsGet6Response, "response.highlights").length, 'last page holds the remaining highlight').toBe(1);
    expect(getResponseValue(highlightsGet6Response, "response.highlights.0.id"), 'no overlap with the first page').toBe(getResponseValue(highlightsPostResponse, "response.id"));
    expect(getResponseValue(highlightsGet6Response, "response.highlights.1"), 'nothing after the last highlight').toBeNull();
    expect(getResponseValue(highlightsGet6Response, "response.nextCursor"), 'nextCursor is null on the last page').toBeNull();

    const linksLinksDeleteResponse = await deleteLink(client, URL_localhost, headers, linkId);
    expect(linksLinksDeleteResponse.statusCode, 'status code').toBe(200);
    expect(getResponseValue(linksLinksDeleteResponse, "response.id"), 'deleted link').toBe(linkId);
    const collectionsCollectionsDeleteResponse = await deleteCollection(client, URL_localhost, headers, getResponseValue(collectionsPostResponse, "response.id"));
    expect(collectionsCollectionsDeleteResponse.statusCode, 'status code').toBe(200);
    expect(getResponseValue(collectionsCollectionsDeleteResponse, "response.id"), 'deleted collection').toBe(getResponseValue(collectionsPostResponse, "response.id"));
});
